import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart';
class KhatmaPage extends StatefulWidget{const KhatmaPage({super.key});@override State<KhatmaPage> createState()=>_KhatmaPageState();}
class _KhatmaPageState extends State<KhatmaPage>{int currentPage=1,completedKhatmas=0,dailyGoal=5;static const totalPages=604;@override void initState(){super.initState();load();}Future<void> load()async{final p=await SharedPreferences.getInstance();setState((){currentPage=p.getInt('khatma_current_page')??1;completedKhatmas=p.getInt('completed_khatmas')??0;dailyGoal=p.getInt('khatma_daily_goal')??5;});}Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setInt('khatma_current_page',currentPage);await p.setInt('completed_khatmas',completedKhatmas);await p.setInt('khatma_daily_goal',dailyGoal);}int get remaining=>totalPages-currentPage+1;int get estimatedDays=>(remaining/dailyGoal).ceil();@override Widget build(BuildContext context){final progress=currentPage/totalPages;return ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[const Icon(Icons.auto_stories,size:60,color:Colors.green),Text('صفحة $currentPage من $totalPages',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:16),LinearProgressIndicator(value:progress,minHeight:12,borderRadius:BorderRadius.circular(10)),const SizedBox(height:12),Text('${(progress*100).toInt()}%')]))),Card(child:ListTile(title:const Text('الهدف اليومي'),subtitle:Text('$dailyGoal صفحات يومياً'),trailing:DropdownButton<int>(value:dailyGoal,items:const [1,2,3,5,10,20].map((v)=>DropdownMenuItem(value:v,child:Text('$v'))).toList(),onChanged:(v)async{if(v==null)return;setState(()=>dailyGoal=v);await save();}))),Card(child:ListTile(title:const Text('تاريخ الانتهاء المتوقع'),subtitle:Text('بعد $estimatedDays يوم'))),FilledButton.icon(onPressed:()async{setState((){if(currentPage<totalPages){currentPage++;}else{completedKhatmas++;currentPage=1;}});await save();},icon:const Icon(Icons.check),label:const Text('أنهيت صفحة'))]);}}
